css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
.split{ display: grid; grid-template-columns: minmax(180px, 1fr) minmax(0, 920px); column-gap: 64px; row-gap: 24px; align-items: start; }
.split-body{ min-width: 0; }
.label{ margin: 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.25; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; max-width: 320px; }
.lead{ margin: 0 0 32px 0; font-family: Switzer, Arial, sans-serif; font-size: 40px; line-height: 1.18; font-weight: 400; letter-spacing: -0.02em; }
.body-text{ margin: 0 0 16px 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.6; font-weight: 400; max-width: 760px; }
.fn{ font-size: 0.62em; line-height: 0; vertical-align: super; }
.fn-link{ color: inherit; text-decoration: none; }
.fn-link:hover{ text-decoration: underline; }
@media screen and (max-width: 991px){.split{ grid-template-columns: minmax(0, 1fr); row-gap: 20px; }
.lead{ font-size: 34px; }}
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }
.label{ font-size: 15px; }
.lead{ font-size: 28px; margin-bottom: 24px; }
.body-text{ font-size: 17px; }}
@media screen and (max-width: 479px){.lead{ font-size: 25px; }}
.what-section { padding-top: 150px; padding-bottom: 150px; background-color: #13181d; color: #ffffff; font-family: Switzer, Arial, sans-serif; scroll-margin-top: 120px; }
.types-panel { display: flex; gap: 24px; margin-top: 96px; padding: 48px; border-radius: 4px; background-color: #d1d1d1; color: #13181d; }
.types-group-rules { display: flex; flex-direction: column; flex: 1 1 0; min-width: 0; }
.types-group-data { display: flex; flex-direction: column; flex: 3 1 0; min-width: 0; }
.types-group-label { margin: 0 0 16px 0; font-size: 12px; line-height: 1.3; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: rgba(19, 24, 29, 0.6); }
.types-grid-rules { display: grid; flex: 1 1 auto; grid-template-columns: minmax(0, 1fr); gap: 24px; }
.types-grid-data { display: grid; flex: 1 1 auto; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
.type-card { display: flex; flex-direction: column; gap: 24px; height: 100%; padding: 28px; border-radius: 4px; background-color: #e4e4e4; box-sizing: border-box; }
.type-head { min-width: 0; }
.type-name { margin: 0; font-size: 28px; line-height: 1.1; font-weight: 400; letter-spacing: -0.01em; }
.type-tagline { margin: 8px 0 0 0; font-size: 17px; line-height: 1.4; color: rgba(19, 24, 29, 0.75); }
.type-practice { min-width: 0; padding-top: 20px; border-top: 1px solid rgba(19, 24, 29, 0.25); }
.type-practice-label { margin: 0 0 6px 0; font-size: 12px; line-height: 1.3; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: rgba(19, 24, 29, 0.6); }
.type-example { margin: 0 0 10px 0; font-size: 19px; line-height: 1.3; font-weight: 500; }
.type-fact { margin: 0; font-size: 16px; line-height: 1.55; color: rgba(19, 24, 29, 0.85); }

@media screen and (max-width: 991px) {
  .what-section { padding-top: 112px; padding-bottom: 112px; }
  .types-panel { flex-direction: column; gap: 40px; margin-top: 64px; padding: 40px; }
  .types-grid-data { grid-template-columns: minmax(0, 1fr); gap: 16px; }
  .types-grid-rules { gap: 16px; }
  .type-card { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 3fr); column-gap: 32px; }
  .type-practice { padding-top: 0; padding-left: 32px; border-top: 0; border-left: 1px solid rgba(19, 24, 29, 0.25); }
}
@media screen and (max-width: 767px) {
  .what-section { padding-top: 88px; padding-bottom: 88px; }
  .types-panel { margin-top: 48px; padding: 24px 20px; }
  .type-card { display: flex; padding: 24px; gap: 20px; }
  .type-practice { padding-top: 18px; padding-left: 0; border-left: 0; border-top: 1px solid rgba(19, 24, 29, 0.25); }
  .type-name { font-size: 24px; }
}
@media screen and (max-width: 479px) {
  .types-panel { margin-left: -8px; margin-right: -8px; padding: 20px 14px; }
  .type-card { padding: 20px; }
}
